/* ===================== BÀI 38 · Quét nhiều chữ số ===================== */
/* Bài 38 · Quét nhiều chữ số (AMTS-EMB-001-M10-L02, MC51-038) — sinh bởi tools/author/mcu8051/l38.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR38=[{"label":"Ví dụ: Quét 4 chữ số bằng vòng trễ","code":"; Ví dụ 1: quét 4 chữ số \"8051\", mỗi chữ số 2 ms\n; Đoạn ở P0 (anode chung, 0 = sáng), chọn chữ số P2.0…P2.3\n; (0 = bật). Bộ đệm hiển thị: 40H…43H. Chạy 100 khung.\n        ORG     0000H\n        MOV     40H,#80H                ; '8'\n        MOV     41H,#0C0H               ; '0'\n        MOV     42H,#92H                ; '5'\n        MOV     43H,#0F9H               ; '1'\n        MOV     R4,#100                 ; số khung\nFRAME:  MOV     R0,#40H                 ; con trỏ bộ đệm\n        MOV     R3,#0FEH                ; chọn chữ số 0 (P2.0 = 0)\nSLOT:   MOV     P2,#0FFH                ; 1) tắt mọi chữ số\n        MOV     P0,@R0                  ; 2) đặt mẫu đoạn mới\n        MOV     P2,R3                   ; 3) bật chữ số mới\n        ACALL   D2MS                    ; giữ khoảng 2 ms\n        INC     R0\n        MOV     A,R3\n        RL      A                       ; chữ số kế tiếp\n        MOV     R3,A\n        CJNE    R0,#44H,SLOT\n        DJNZ    R4,FRAME\n        MOV     P2,#0FFH                ; dừng quét: tắt hết\n        SJMP    $\nD2MS:   MOV     R6,#4                   ; 1 + 4 x 499 + 2 = 1 999 chu kỳ\nDL1:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DL1\n        RET\n        END\n","note":"Mỗi khe: tắt P2 (FFH) → đặt mẫu P0 → bật chữ số bằng R3 (FEH, FDH, FBH, F7H), giữ 2 001 chu kỳ. Một khe 2 013 chu kỳ, một khung 8 056 chu kỳ ≈ 124 Hz. 100 khung = 805 611 chu kỳ ≈ 0,81 s; mỗi chữ số sáng ≈ 25 % thời gian.","dev":{"seg":true},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Đổi mẫu đoạn khi chữ số cũ còn bật","code":"; Ví dụ 2 (bẫy): đổi mẫu đoạn khi chữ số cũ còn bật\n; Bỏ bước \"tắt mọi chữ số\": trong lúc lệnh MOV P2,R3 chạy,\n; chữ số cũ hiện mẫu của chữ số mới (bóng ma). 50 khung.\n        ORG     0000H\n        MOV     40H,#80H\n        MOV     41H,#0C0H\n        MOV     42H,#92H\n        MOV     43H,#0F9H\n        MOV     R4,#50\nFRAME:  MOV     R0,#40H\n        MOV     R3,#0FEH\nSLOT:   MOV     P0,@R0                  ; chữ số cũ VẪN bật: hiện mẫu mới\n        MOV     P2,R3                   ; giờ mới đổi chữ số\n        ACALL   D2MS\n        INC     R0\n        MOV     A,R3\n        RL      A\n        MOV     R3,A\n        CJNE    R0,#44H,SLOT\n        DJNZ    R4,FRAME\n        MOV     P2,#0FFH\n        SJMP    $\nD2MS:   MOV     R6,#4                   ; 1 + 4 x 499 + 2 = 1 999 chu kỳ\nDL1:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DL1\n        RET\n        END\n","note":"Thiếu bước tắt: lệnh MOV P0,@R0 đổi mẫu khi chữ số cũ còn bật. Bấm Từng bước tới khe thứ hai: chữ số 0 hiện “0” thay vì “8” trong 2 chu kỳ máy cho tới khi MOV P2,R3 chạy. Kiểm thiết bị ghi: mẫu cuối cùng chữ số 0, 1, 2 từng hiện là mẫu của chữ số bên phải.","dev":{"seg":true},"fosc":12000000,"speed":"real"},{"label":"Lỗi: Quét quá chậm, mắt thấy nhấp nháy","code":"; Ví dụ 3 (lỗi): mỗi chữ số 20 ms, khung 80 ms\n; Tần số quét 12,5 Hz: mắt thấy từng chữ số nhấp nháy.\n        ORG     0000H\n        MOV     40H,#80H\n        MOV     41H,#0C0H\n        MOV     42H,#92H\n        MOV     43H,#0F9H\n        MOV     R4,#10                  ; 10 khung x 80 ms = 0,8 s\nFRAME:  MOV     R0,#40H                 ; con trỏ bộ đệm\n        MOV     R3,#0FEH                ; chọn chữ số 0 (P2.0 = 0)\nSLOT:   MOV     P2,#0FFH                ; 1) tắt mọi chữ số\n        MOV     P0,@R0                  ; 2) đặt mẫu đoạn mới\n        MOV     P2,R3                   ; 3) bật chữ số mới\n        ACALL   D2MS                    ; (thật ra khoảng 20 ms)\n        INC     R0\n        MOV     A,R3\n        RL      A                       ; chữ số kế tiếp\n        MOV     R3,A\n        CJNE    R0,#44H,SLOT\n        DJNZ    R4,FRAME\n        MOV     P2,#0FFH                ; dừng quét: tắt hết\n        SJMP    $\nD2MS:   MOV     R6,#40                  ; 1 + 40 x 499 + 2 = 19 963 chu kỳ\nDL1:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DL1\n        RET\n        END\n","note":"Cùng chương trình nhưng mỗi khe 19 977 chu kỳ (≈ 20 ms): khung 79 912 chu kỳ ≈ 80 ms, tần số 12,5 Hz. Ở tốc độ Thời gian thực, các chữ số chớp tắt lần lượt. Tỉ lệ sáng vẫn 1/4: nhấp nháy do khung dài, không do thiếu sáng.","dev":{"seg":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Nhịp 2 ms từ Timer 0 tự nạp","code":"; Ví dụ 4: nhịp quét từ Timer 0 (hỏi vòng cờ TF0)\n; Chế độ 2 tự nạp: tràn đúng mỗi 250 chu kỳ máy (250 us ở\n; 12 MHz). 8 lần tràn = 2 ms cho một chữ số. Hiện \"12.34\".\n        ORG     0000H\n        MOV     40H,#0F9H               ; '1'\n        MOV     41H,#24H                ; '2' kèm dấu chấm (bit 7 = 0)\n        MOV     42H,#0B0H               ; '3'\n        MOV     43H,#99H                ; '4'\n        MOV     TMOD,#02H               ; Timer 0, chế độ 2\n        MOV     TH0,#06H                ; giá trị nạp lại: 256 - 250\n        MOV     TL0,#06H\n        SETB    TR0\n        MOV     R4,#50                  ; 50 khung x 8 ms\nFRAME:  MOV     R0,#40H\n        MOV     R3,#0FEH\nSLOT:   MOV     P2,#0FFH\n        MOV     P0,@R0\n        MOV     P2,R3\n        MOV     R5,#8                   ; 8 nhịp x 250 us = 2 ms\nTICK:   JNB     TF0,TICK                ; chờ cờ tràn\n        CLR     TF0\n        DJNZ    R5,TICK\n        INC     R0\n        MOV     A,R3\n        RL      A\n        MOV     R3,A\n        CJNE    R0,#44H,SLOT\n        DJNZ    R4,FRAME\n        MOV     P2,#0FFH\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Timer 0 chế độ 2 tràn mỗi 250 chu kỳ (TH0 = 06H tự nạp vào TL0). Vòng JNB TF0,$ chờ cờ, CLR TF0 xóa cờ, R5 đếm 8 lần tràn = 2 000 chu kỳ mỗi khe, không trôi. Tổng 15 + 1 600 × 250 + 14 = 400 029 chu kỳ. Chữ số 1 có dấu chấm (24H = A4H với bit 7 = 0).","dev":{"seg":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Từ số nhị phân tới các chữ số (DIV AB)","code":"; Ví dụ 5: số nhị phân 245 thành ba chữ số rồi quét\n; DIV AB: A = thương, B = số dư. Chữ số 0 (trái) để trống.\n        ORG     0000H\n        MOV     30H,#245\n        MOV     A,30H\n        MOV     B,#100\n        DIV     AB                      ; A = 2, B = 45\n        MOV     DPTR,#SEGCA\n        MOVC    A,@A+DPTR\n        MOV     41H,A                   ; hàng trăm\n        MOV     A,B\n        MOV     B,#10\n        DIV     AB                      ; A = 4, B = 5\n        MOVC    A,@A+DPTR\n        MOV     42H,A                   ; hàng chục\n        MOV     A,B\n        MOVC    A,@A+DPTR\n        MOV     43H,A                   ; hàng đơn vị\n        MOV     40H,#0FFH               ; trống\n        MOV     R4,#50\nFRAME:  MOV     R0,#40H                 ; con trỏ bộ đệm\n        MOV     R3,#0FEH                ; chọn chữ số 0 (P2.0 = 0)\nSLOT:   MOV     P2,#0FFH                ; 1) tắt mọi chữ số\n        MOV     P0,@R0                  ; 2) đặt mẫu đoạn mới\n        MOV     P2,R3                   ; 3) bật chữ số mới\n        ACALL   D2MS                    ; giữ khoảng 2 ms\n        INC     R0\n        MOV     A,R3\n        RL      A                       ; chữ số kế tiếp\n        MOV     R3,A\n        CJNE    R0,#44H,SLOT\n        DJNZ    R4,FRAME\n        MOV     P2,#0FFH                ; dừng quét: tắt hết\n        SJMP    $\nD2MS:   MOV     R6,#4                   ; 1 + 4 x 499 + 2 = 1 999 chu kỳ\nDL1:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DL1\n        RET\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","note":"245 ÷ 100 = 2 dư 45; 45 ÷ 10 = 4 dư 5. DIV AB đặt thương vào A, số dư vào B, tốn 4 chu kỳ. Tra bảng rồi ghi bộ đệm 41H…43H; 40H = FFH để trống. Phần tính chạy một lần (31 chu kỳ), phần quét chạy 50 khung.","dev":{"seg":true},"fosc":12000000,"speed":"real"}];
const sim38=makeSim51(document.getElementById("m51-l38"),{id:"s38",presets:PR38,ram:256});
makeEx51(document.getElementById("ex-l38"),"l38",[{"t":"Giá trị nạp Timer 0 cho một khe quét","d":"<p>Thạch anh 12 MHz (1 chu kỳ máy = 1 µs). Hai ô <code>30H<\/code> (byte cao) và <code>31H<\/code> (byte thấp) chứa thời gian một khe quét T tính bằng µs, 1 ≤ T ≤ 65 535. Tính giá trị nạp Timer 0 chế độ 1 (16 bit) để tràn sau đúng T chu kỳ máy: N = 65 536 − T. Ghi byte cao của N (giá trị cho TH0) vào ô <code>32H<\/code>, byte thấp (cho TL0) vào ô <code>33H<\/code>. Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: T = 2 000 = 07D0H → N = 63 536 = F830H → <code>32H = F8H<\/code>, <code>33H = 30H<\/code>.<\/p>","start":"        ORG     0000H\n; 30H:31H = thời gian một khe (us), 32H:33H = TH0:TL0\n        MOV     A,#0FFH\n        CLR     C\n        SUBB    A,31H\n        MOV     33H,A\n        MOV     A,#0FFH\n        SUBB    A,30H\n        MOV     32H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":7,"0x31":208,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":7,"0x31":208,"0x32":248,"0x33":48}}},{"setup":{"iram":{"0x30":3,"0x31":232,"0x32":238,"0x33":238},"regs":{"PSW":128}},"expect":{"iram":{"0x30":3,"0x31":232,"0x32":252,"0x33":24}}},{"setup":{"iram":{"0x30":9,"0x31":196,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":9,"0x31":196,"0x32":246,"0x33":60}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":1,"0x32":255,"0x33":255}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":255,"0x33":0}}}]},"hints":["Code mẫu tính 65 535 − T (FFFFH − T): kết quả lệch 1. Thử T = 1: phải ra FFFFH.","65 536 − T trong phép trừ 16 bit chính là 0000H − T (số mượn ra khỏi bit 15 bị bỏ). Bắt đầu với A = 0 và CY = 0.","Trừ 16 bit bắt đầu từ byte thấp; byte cao dùng lại số mượn."],"why":"Timer chế độ 1 đếm lên và bật TF0 khi chuyển từ FFFFH sang 0000H, nên từ N phải đếm đúng 65 536 − N lần. Viết 0 − T với SUBB 16 bit cho kết quả đúng mọi T, kể cả T = 1 (FFFFH) mà cách FFFFH − T làm sai."},{"t":"Bộ đệm hiển thị có ẩn số 0 ở đầu","d":"<p>Ô <code>30H<\/code> chứa số 0–255. Ghi mã anode chung (bảng <code>SEGCA<\/code> có sẵn) của hàng trăm, hàng chục, hàng đơn vị vào bộ đệm <code>40H<\/code>, <code>41H<\/code>, <code>42H<\/code> (trái sang phải). <b>Ẩn số 0 ở đầu<\/b>: chữ số 0 đứng trước chữ số khác 0 đầu tiên ghi <code>FFH<\/code> (tắt mọi đoạn); hàng đơn vị luôn hiện, kể cả khi số bằng 0. Số 0 nằm giữa (như 100, 205) vẫn hiện. Ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: 245 → <code>A4H 99H 92H<\/code>; 7 → <code>FFH FFH F8H<\/code>; 100 → <code>F9H C0H C0H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     DPTR,#SEGCA\n        MOV     A,30H\n        MOV     B,#100\n        DIV     AB\n        MOVC    A,@A+DPTR\n        MOV     40H,A                   ; hàng trăm (chưa ẩn số 0)\n        MOV     A,B\n        MOV     B,#10\n        DIV     AB\n        MOVC    A,@A+DPTR\n        MOV     41H,A                   ; hàng chục (chưa ẩn số 0)\n        MOV     A,B\n        MOVC    A,@A+DPTR\n        MOV     42H,A                   ; hàng đơn vị\n        SJMP    $\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":245,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":245,"0x40":164,"0x41":153,"0x42":146}}},{"setup":{"iram":{"0x30":7,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":7,"0x40":255,"0x41":255,"0x42":248}}},{"setup":{"iram":{"0x30":0,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":0,"0x40":255,"0x41":255,"0x42":192}}},{"setup":{"iram":{"0x30":100,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":100,"0x40":249,"0x41":192,"0x42":192}}},{"setup":{"iram":{"0x30":10,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":10,"0x40":255,"0x41":249,"0x42":192}}},{"setup":{"iram":{"0x30":99,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":99,"0x40":255,"0x41":144,"0x42":144}}},{"setup":{"iram":{"0x30":255,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":255,"0x40":164,"0x41":146,"0x42":146}}}]},"hints":["Code mẫu đã tách đủ ba chữ số bằng DIV AB (chia 100 rồi chia 10) nhưng luôn hiện cả số 0 ở đầu.","Giữ hàng trăm, hàng chục ở R2, R3 trước khi tra bảng; ghi sẵn FFH vào 40H, 41H rồi chỉ ghi đè khi cần hiện.","Hai trường hợp theo hàng trăm: khác 0 thì luôn hiện hàng chục; bằng 0 thì hàng chục chỉ hiện khi khác 0."],"why":"Bộ đệm hiển thị tách việc “tính chữ số” (chạy khi giá trị đổi) khỏi việc quét (chạy mỗi 2 ms). Ẩn số 0 ở đầu là quy tắc theo vị trí: chỉ ẩn khi mọi chữ số bên trái cũng là 0 — bộ thử 100 bắt lỗi ẩn nhầm số 0 ở giữa, bộ thử 0 bắt lỗi ẩn cả hàng đơn vị."},{"t":"Một khe quét trong ≤ 18 chu kỳ","d":"<p>Viết một <b>khe quét<\/b> (phần việc chạy ở mỗi nhịp 2 ms) cho LED 4 chữ số của bo: đoạn ở P0, chọn chữ số k bằng P2.k = 0 (P2.0…P2.3), các bit khác của P2 bằng 1. Ô <code>38H<\/code> chứa số thứ tự k (0–3) của chữ số cần bật; bộ đệm <code>40H<\/code>…<code>43H<\/code> chứa mẫu đoạn. Một khe gồm: tắt mọi chữ số (<code>P2 = FFH<\/code>), xuất mẫu <code>[40H + k]<\/code> ra P0, bật chữ số k (<code>P2<\/code> = FEH, FDH, FBH hoặc F7H), rồi tăng k vòng tròn: 0 → 1 → 2 → 3 → 0. Bộ đệm giữ nguyên. Code mẫu đúng nhưng chậm (vòng lặp RL, so sánh CJNE). Hãy viết lại để chạy <b>không quá 18 chu kỳ máy<\/b> (tính cả <code>SJMP $<\/code>) với mọi k và dài <b>không quá 30 byte<\/b>.<\/p><p>Ví dụ: k = 3, bộ đệm 80H C0H 92H F9H → <code>P0 = F9H<\/code>, <code>P2 = F7H<\/code>, <code>38H = 00H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     P2,#0FFH                ; tắt mọi chữ số\n        MOV     A,38H\n        ADD     A,#40H\n        MOV     R0,A\n        MOV     P0,@R0                  ; mẫu đoạn của chữ số 38H\n        MOV     R2,38H\n        MOV     A,#0FEH                 ; tính mẫu chọn bằng vòng lặp\nROT:    CJNE    R2,#0,SH\n        SJMP    OUT\nSH:     RL      A\n        DEC     R2\n        SJMP    ROT\nOUT:    MOV     P2,A                    ; bật chữ số\n        INC     38H\n        MOV     A,38H\n        CJNE    A,#4,FIN\n        MOV     38H,#0\nFIN:    SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x38":0,"0x40":128,"0x41":192,"0x42":146,"0x43":249}},"expect":{"iram":{"0x38":1,"0x40":128,"0x41":192,"0x42":146,"0x43":249},"ports":{"P0":128,"P2":254}}},{"setup":{"iram":{"0x38":1,"0x40":249,"0x41":36,"0x42":176,"0x43":153}},"expect":{"iram":{"0x38":2,"0x40":249,"0x41":36,"0x42":176,"0x43":153},"ports":{"P0":36,"P2":253}}},{"setup":{"iram":{"0x38":2,"0x40":255,"0x41":164,"0x42":153,"0x43":146}},"expect":{"iram":{"0x38":3,"0x40":255,"0x41":164,"0x42":153,"0x43":146},"ports":{"P0":153,"P2":251}}},{"setup":{"iram":{"0x38":3,"0x40":128,"0x41":192,"0x42":146,"0x43":249}},"expect":{"iram":{"0x38":0,"0x40":128,"0x41":192,"0x42":146,"0x43":249},"ports":{"P0":249,"P2":247}}},{"setup":{"iram":{"0x38":3,"0x40":18,"0x41":52,"0x42":86,"0x43":120}},"expect":{"iram":{"0x38":0,"0x40":18,"0x41":52,"0x42":86,"0x43":120},"ports":{"P0":120,"P2":247}}},{"setup":{"iram":{"0x38":0,"0x40":18,"0x41":52,"0x42":86,"0x43":120}},"expect":{"iram":{"0x38":1,"0x40":18,"0x41":52,"0x42":86,"0x43":120},"ports":{"P0":18,"P2":254}}}],"maxCyc":18,"maxBytes":30},"hints":["Chạy code mẫu với k = 3: vòng RL chạy 3 lần, CJNE chạy 4 lần — số chu kỳ đổi theo k. Khe quét tốt có thời gian cố định.","(k + 1) mod 4 = (k + 1) AND 03H: không cần so sánh. XCH A,38H vừa cất k mới vừa lấy lại k cũ.","Mẫu chọn chữ số nên tra bảng thay vì xoay theo k; một bảng nhỏ đặt gần lệnh tra đọc được bằng MOVC theo PC."],"why":"Khe quét chạy 500 lần mỗi giây (mỗi 2 ms), nên mỗi chu kỳ bớt được nhân 500. Lời giải mẫu chạy 17 chu kỳ, 28 byte và không phụ thuộc k: ANL thay CJNE, bảng chọn thay vòng RL. Thời gian cố định còn giúp độ sáng các chữ số đều nhau."}]);

makeQuiz("quiz38","score38",[{"q": "Bốn chữ số quét, mỗi khe 2,5 ms. Tần số quét và tỉ lệ thời gian sáng của mỗi chữ số là bao nhiêu?", "o": ["400 Hz, 25 %", "100 Hz, 100 %", "100 Hz, 25 %", "25 Hz, 50 %"], "a": 2, "e": "Khung = 4 × 2,5 ms = 10 ms → f = 100 Hz. Mỗi chữ số chỉ bật 1 trong 4 khe → 25 %. 400 Hz là tần số đổi khe, không phải tần số khung."}, {"q": "Thứ tự nào trong một khe quét tránh được bóng ma?", "o": ["Đặt mẫu đoạn mới → bật chữ số mới → tắt chữ số cũ", "Bật chữ số mới → đặt mẫu đoạn mới", "Đặt mẫu đoạn mới → đổi chân chọn bằng một lệnh", "Tắt mọi chữ số → đặt mẫu đoạn mới → bật chữ số mới"], "a": 3, "e": "Đổi P0 khi chữ số cũ còn bật làm chữ số cũ hiện mẫu mới; đổi P2 trước làm chữ số mới hiện mẫu cũ. Tắt hết trước tiên thì không có lúc nào sai mẫu."}, {"q": "Timer 0 chế độ 2, TH0 = 06H, thạch anh 12 MHz. Cờ TF0 bật cách nhau bao lâu?", "o": ["250 µs", "256 µs", "6 µs", "3 000 µs"], "a": 0, "e": "Chế độ 2 đếm từ giá trị nạp 06H tới tràn FFH → 00H: 256 − 6 = 250 chu kỳ máy, mỗi chu kỳ 1 µs ở 12 MHz. Phần cứng tự nạp lại nên không trôi."}, {"q": "Cần Timer 0 chế độ 1 tràn sau 2 000 µs ở 12 MHz. Nạp TH0:TL0 bằng bao nhiêu?", "o": ["07D0H", "F82FH", "F830H", "0830H"], "a": 2, "e": "N = 65 536 − 2 000 = 63 536 = F830H. 07D0H là chính số 2 000; F82FH = 65 535 − 2 000, lệch 1 chu kỳ."}, {"q": "Trong một ứng dụng, LED 4 chữ số quét bằng vòng trễ 2 ms và chương trình không còn đọc kịp nút bấm. Cách sửa phù hợp nhất?", "o": ["Tăng thời gian trễ lên 20 ms", "Lấy nhịp quét từ timer, mỗi nhịp chạy một khe ngắn, thời gian còn lại đọc nút", "Bỏ bộ đệm hiển thị, tính chữ số trong mỗi khe", "Hiện tĩnh cả 4 chữ số bằng P0"], "a": 1, "e": "Vòng trễ giữ CPU bận suốt 2 ms. Với nhịp timer, khe quét chỉ tốn vài chục chu kỳ mỗi 2 ms, CPU rảnh cho việc khác. Tăng trễ gây nhấp nháy; hiện tĩnh không đủ chân."}]);

